  test('empty intent → blocked + needs="send a prompt to start"', async () => {
    const root = mkdtempSync(join(tmpdir(), 'preseed-'))
    const orig = process.env.THYROX_CONFIG_HOME
    process.env.THYROX_CONFIG_HOME = root
    try {
