      expect(state.respawnFlags).toEqual(['--fork-session'])
    } finally {
      if (orig === undefined) delete process.env.THYROX_CONFIG_HOME
      else process.env.THYROX_CONFIG_HOME = orig
      rmSync(root, { recursive: true, force: true })
    }
  })

